    public BankingProduct testCreate() throws Throwable {
    BankingProduct entity = null;

    LOGGER.info( "BankingProductTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a BankingProduct");

    StringBuilder msg = new StringBuilder( "-- Failed to create a BankingProduct" );

    try {
        entity = service.createBankingProduct( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getBankingProductId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a BankingProduct with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

