    /**
     * Tests getting all BankingProducts.
     *
     * @return    Collection
     */
    public List<BankingProduct> testGetAll() throws Throwable {
    LOGGER.info( "BankingProductTest:testGetAll() - Retrieving Collection of BankingProducts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all BankingProduct : " );
    List<BankingProduct> collection  = null;

    try {
        // call the static get method on the BankingProductService
        collection = service.getAllBankingProduct();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            BankingProduct currEntity  = null;
            Iterator<BankingProduct> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBankingProductId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

